import { defineConfig, devices } from '@playwright/test';

/**
 * End-to-end tests run against a running stack — by default the production compose behind nginx
 * (http://localhost:8080). Email OTPs are read from Mailpit (MAILPIT_URL) via
 * tests/e2e/utils/mailpit.ts; admin TOTP codes are generated by tests/e2e/utils/totp.ts.
 *
 * Local run against the e2e stack (docker-compose.e2e.yml; values in .env.e2e):
 *   C="docker compose --env-file .env.e2e -f docker-compose.prod.yml -f docker-compose.e2e.yml"
 *   $C up -d --build && $C run --rm seed
 *   E2E_BASE_URL=http://localhost:8080 MAILPIT_URL=http://localhost:8026 \
 *     E2E_ADMIN_PASSWORD=<SEED_SUPER_ADMIN_PASSWORD> corepack pnpm exec playwright test
 *
 * Projects:
 *   setup     the seeded super admin signs in (email code → TOTP enrollment) and stores the session
 *   chromium  desktop specs (critical flow + negative cases); depends on setup
 *   mobile    Pixel 7 layout checks of the member pages (*.mobile.spec.ts)
 *
 * State that must survive between runs against the same stack (the admin's TOTP secret) lives in
 * tests/e2e/.state/ (git-ignored). Delete it together with the stack data (`$C down -v`).
 */
const isCI = !!process.env.CI;
const baseURL = process.env.E2E_BASE_URL ?? 'http://localhost:8080';

export default defineConfig({
  testDir: 'tests/e2e',
  outputDir: 'test-results',
  fullyParallel: true,
  forbidOnly: isCI,
  retries: isCI ? 2 : 0,
  workers: isCI ? 2 : 4,
  timeout: 90_000,
  expect: { timeout: 15_000 },
  reporter: isCI
    ? [['list'], ['github'], ['html', { open: 'never', outputFolder: 'playwright-report' }]]
    : [['list'], ['html', { open: 'never', outputFolder: 'playwright-report' }]],
  use: {
    baseURL,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    actionTimeout: 15_000,
    navigationTimeout: 30_000,
    locale: 'en-US',
    timezoneId: 'UTC',
  },
  projects: [
    { name: 'setup', testMatch: /.*\.setup\.ts/, use: { ...devices['Desktop Chrome'] } },
    {
      name: 'chromium',
      testIgnore: [/.*\.setup\.ts/, /.*\.mobile\.spec\.ts/],
      dependencies: ['setup'],
      use: { ...devices['Desktop Chrome'] },
    },
    { name: 'mobile', testMatch: /.*\.mobile\.spec\.ts/, use: { ...devices['Pixel 7'] } },
  ],
});
